@spec arrange_page_spec  src=tests/specs/arrange_page_spec.lua  loc=1111  cases=47
@exercises commandManager (h.cmgr), configManager (h.cm), arrangeManager (am)
@surface   cmgr:registerAll, cm:set, cmgr:push, am:tracksTakes, cmgr:invoke, cm:get, am:resizeTake, am:trimHead, am:trackSlots
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.SetMediaItemSelected, reaper:setCursor

# Intent
  Pin-tests for arrangePage's Page interface and arrange-scope edit commands.
  Cursor mechanics, off-screen no-op, and selection-precedence: arrange_view_spec.

# Helpers
  @fn newArrangePage(cm, ds, cmgr, chrome, gui)  @ 49-57
  @fn twoSelected(h)  @ 61-80
      -- Two instances of slot 0, one row each at QN 0 and 1, with rows 0..1 banded.
      -- The siblings at QN 10 and 20 are what slots 0 and 1 clone from.

# Cases
  @case 'bind / unbind are no-ops — arrange page never re-keys cm'  [harness]  @ 84-94
  @case 'focusState before any render returns both bits false'  [harness]  @ 98-105
  @case 'arrange-scope is registered at module load (cursorRight invokable)'  [harness]  @ 109-116
  @case 'arrange-scope place commands are registered (drop0/dropA/dropZ invokable)'  [harness]  @ 120-131
  @case 'a place-command drop advances the cursor by cm.arrangeAdvanceBy rows'  [harness]  @ 135-158
  @case 'arrangeAdvanceBy0..9 set cm.arrangeAdvanceBy at project tier'  [harness]  @ 162-173
  @case 'chained Super-D walks down — each clone becomes the selection for the next'  [harness]  @ 177-196
  @case 'a place-command drop inherits the length of an existing instance'  [harness]  @ 200-222
  @case 'arrangeNudgeForward moves the cursor take by one row'  [harness]  @ 226-240
  @case 'arrangeNudgeForward moves a take taller than one row'  [harness]  @ 244-259
  @case 'arrangeEdgeDown lengthens the cursor take by one row'  [harness]  @ 263-281
  @case 'growing a trimmed take moves its end, leaving the head where it was'  [harness]  @ 285-307
  @case 'arrangeEdgeDown silently no-ops at the take-source length cap'  [harness]  @ 311-326
  @case 'arrangeEdgeUp reduces the cursor take by one row'  [harness]  @ 330-346
  @case 'arrangeDeleteTake removes the cursor take'  [harness]  @ 350-364
  @case 'deleteSlot forever-deletes the cursor take\'s slot behind a confirm'  [harness]  @ 370-394
  @case 'deleteSlot no-ops with the cursor off every take'  [harness]  @ 398-414
  @case 'arrangeNudgeForward is a no-op when the next row is occupied'  [harness]  @ 418-434
  @case 'arrangeNudgeBack is a no-op when the take is already at row 0'  [harness]  @ 438-452
  @case 'arrangeEdgeDown against a flush neighbour stores intent; rendered is gap-capped'  [harness]  @ 456-475
  @case 'arrangeNudgeForward steps past a neighbour without a start-collision'  [harness]  @ 479-499
  @case 'arrangeNudgeForward truncates the displaced take when stepping past'  [harness]  @ 503-525
  @case 'arrangeDive switches to the tracker for the cursor MIDI take'  [harness]  @ 529-544
  @case 'createSlot dives the tracker onto the freshly-minted take'  [harness]  @ 548-563
  @case 'arrangeDive over an audio take still switches and restores (no take pinned)'  [harness]  @ 567-581
  @case 'arrangeDive over empty space switches and restores'  [harness]  @ 585-597
  @case 'the dive carries the caret QN, and carries none over empty space'  [harness]  @ 603-622
  @case 'kb edit acts on the cursor take when nothing is selected'  [harness]  @ 626-644
  @case 'kb delete no-ops when the cursor sits off every take'  [harness]  @ 648-666
  @case 'kb nudge no-ops when cursor sits on empty space'  [harness]  @ 670-687
  @case 'an edit command is a no-op when the cursor is over empty space'  [harness]  @ 691-706
  @case 'a second delete finds an empty cell under the cursor — no-op'  [harness]  @ 710-728
  @case 'seedCursorFromReaper lands the cursor on the selected take'  [harness]  @ 732-749
  @case 'seedCursorFromReaper falls back to the edit-cursor row'  [harness]  @ 753-767
  @case 'arrangeTakeProperties routes the focused MIDI take through the tracker facade'  [harness]  @ 776-789
  @case 'arrangeTakeProperties is a no-op on an audio take'  [harness]  @ 793-806
  @case 'arrangeDuplicateBelow drops a pooled clone at the focused take\'s append point'  [harness]  @ 810-826
  @case 'arrangeDuplicateBelow is silent for want of room and on audio takes'  [harness]  @ 830-848
  @case 'arrangeNextVariant past the last of the family swaps the target for a fresh variant'  [harness]  @ 852-883
  @case 'arrangeDuplicateBelow then arrangeNextVariant forks the copy onto a fresh slot'  [harness]  @ 889-913
  @case 'replace mode: a drop swaps the take under the cursor, keeping its start'  [harness]  @ 919-946
  @case 'a replace with a selection held replaces every selected take'  [harness]  @ 950-967
  @case 'the replacements become the selection'  [harness]  @ 971-983
  @case 'a shorter replacement pulls the cursor back inside it'  [harness]  @ 987-1015
  @case 'replace mode disarms on the drop it reinterprets — the next drop places'  [harness]  @ 1019-1047
  @case 'a cursor move disarms replace mode'  [harness]  @ 1051-1077
  @case 'a second arrangeReplaceMode disarms — the mode is a toggle'  [harness]  @ 1081-1108

